def sh(*args, stdin_text=None):
    r = subprocess.run(args, capture_output=True, text=True, input=stdin_text)
    if r.returncode != 0:
        sys.exit(f"✗ {' '.join(args)}\n{r.stdout}\n{r.stderr}")
    return r.stdout

def main() -> None:
    for did in IDS:
        sh("python3", "scripts-translate/merge-r84.py", did)
        sh("git", "add", "content/books/hadith-1es.json",
           "scripts-translate/savant-registry.json",
           f"tr-tmp/{did}.html", f"tr-tmp/{did}.src.html", f"tr-tmp/{did}.gt.html")
        sh("git", "commit", "-q", "-F", "-", stdin_text=MSGS[did])
        head = sh("git", "log", "--oneline", "-1").strip()
        print(f"✓ {did} commit : {head[:90]}…")
    print("commits R84 terminés")

if __name__ == "__main__":
    main()
